Arguments: {"title":"Inspect sr-filters and advanced contents","cwd":null,"code":"const tabId = 343605414;
console.log(await browserjs(tabId, () => {
  const srFilters = document.getElementById('sr-filters');
  const advanced = document.getElementById('advanced');

  function summarize(el) {
    if (!el) return null;
    const inputs = Array.from(el.querySelectorAll('input, select, label')).map(x => ({
      tag: x.tagName,
      id: x.id,
      name: x.name,
      type: x.type,
      value: x.value,
      text: x.textContent.trim()
    }));
    return {
      id: el.id,
      inputsCount: inputs.length,
      sampleInputs: inputs.slice(0, 30)
    };
  }

  return {
    srFilters: summarize(srFilters),
    advanced: summarize(advanced)
  };
}));
"}
